          tf('If f(g(x)) = x on the domain of g and g(f(x)) = x on the domain of f, then g is the inverse of f.', key=True, note='This is the composition test.'),
          tf('f(x) = x + 3 and g(x) = x - 3 are not inverses, because f(g(1)) = 7.', key=False, note='f(g(1)) = f(-2) = 1. They are inverses.'),
