          tf('f(x) = x² restricted to x ≤ 0 has the inverse f⁻¹(x) = -√x.', key=True, note='For x ≤ 0, -√(x²) = x.'),
          tf('f(x) = x² + 1 is one-to-one on all real numbers.', key=False, note='f(1) = f(-1) = 2.'),
