    # ------------------------------------------------------------------ F-LE.A.1.a
    S('HSF-LE.A.1.a', 'Prove that linear functions grow by equal differences and exponential functions grow by equal factors over equal intervals',
      main=[
          work('f(x) = 3x + 5. Show that f grows by equal differences over equal intervals: find f(x + h) - f(x) in simplest form, and explain why it does not depend on x.', 'f(x + h) - f(x) =',
               method='Algebra showing f(x + h) - f(x) = 3(x + h) + 5 - (3x + 5) = 3h, and the statement that 3h depends only on the interval length h.',
               key='3h', note='Form required: the simplified difference and the explanation.'),
          work('g(x) = 4 · 2^x. Show that g grows by equal factors over equal intervals: find g(x + h) ÷ g(x) in simplest form, and explain why it does not depend on x.', 'g(x + h) ÷ g(x) =',
               method='Algebra showing 4 · 2^(x+h) ÷ (4 · 2^x) = 2^h, and the statement that 2^h depends only on h.',
               key='2^h', note='Form required: the simplified ratio and the explanation.'),
          sa('A table shows x = 0, 2, 4, 6 and y = 5, 11, 17, 23.\nIs the relationship linear or exponential? Explain using equal intervals.', 'Answer:',
             key='Linear: over each interval of 2, y increases by the same amount, 6.', note='Form required: the type and the reason.'),
          mc('A table shows x = 0, 1, 2, 3 and y = 80, 40, 20, 10.\nWhich description is correct?', ['Exponential: y is multiplied by {1/2} each time x increases by 1',
             'Linear: y decreases by 40 each time', 'Linear: y decreases by 20 each time', 'Neither linear nor exponential'],
             note='The differences are -40, -20, -10 (not equal), but the ratios are all {1/2}.'),
          tf('A table with y-values 2, 5, 10, 17 for x = 0, 1, 2, 3 is linear.', key=False, note='The differences 3, 5, 7 are not equal.'),
      ],
      back=[
          B('Tell linear from nonlinear functions', '8.F.A.3', [
              sa('Is y = x² + 1 linear? Use the points (0, 1), (1, 2), and (2, 5) to explain.', 'Answer:', key='No. y increases by 1 and then by 3, so the rate is not constant.',
                 note='Form required: the answer and the reason.'),
              sa('Is y = 4 - 2x linear? Why?', 'Answer:', key='Yes. It has the form y = mx + b with slope -2.', note='Form required: the answer and the reason.'),
              mc('Which function is linear?', ['y = 0.5x - 3', 'y = x²', 'y = 2^x', 'y = 1 ÷ x'], note='Only y = 0.5x - 3 has the form y = mx + b.'),
              tf('The graph of a linear function is a straight line.', key=True, note='That is why it is called linear.'),
              tf('The area of a square, A = s², is a linear function of s.', key=False, note='Its graph curves; the area grows by 1, 3, 5, ... for s = 0, 1, 2, 3.'),
          ]),
          B('Compare average rates of change over intervals', 'HSF-IF.B.6', [
              sa('f(x) = 3x + 5.\nFind the average rate of change from x = 0 to x = 10.', 'Rate:', key='3', note='Any equivalent form.'),
              sa('g(x) = 4 · 2^x.\nFind the average rate of change from x = 0 to x = 1, and from x = 1 to x = 2.', 'Answer:', key='4 and 8',
                 note='Form required: both rates. (8 - 4) ÷ 1 and (16 - 8) ÷ 1.'),
              mc('What is the average rate of change of 5 · 3^x from x = 0 to x = 2?', ['20', '15', '45', '40'], note='(45 - 5) ÷ 2 = 20.'),
              tf('An exponential growth function has a larger average rate of change on later intervals of the same length.', key=True, note='Its outputs, and their changes, keep multiplying.'),
              tf('The average rate of change of 2^x from x = 0 to x = 3 is 2.', key=False, note='(8 - 1) ÷ 3 = {7/3}.'),
          ]),
      ],
      f1=B('Derive the formula for the sum of a finite geometric series', 'HSA-SSE.B.4', [
          work('Let S = 1 + 2 + 4 + ... + 2⁹. Show that 2S - S = 2¹⁰ - 1, and find S.', 'S =',
               method='2S written as 2 + 4 + ... + 2¹⁰, then subtracting S so that every term except 2¹⁰ and 1 cancels.',
               key='1,023', note='Form required: the subtraction and the value of S.'),
          sa('Use S = a(1 - r^n) ÷ (1 - r) to find the sum of the first 6 terms of 1, 3, 9, ...', 'Sum:', key='364', note='Any equivalent form. (1 - 729) ÷ (1 - 3).'),
          mc('When deriving the sum formula, why do we multiply S by r?', ['So that S - rS cancels all but two terms', 'To make every term equal', 'To double the sum', 'To make r equal 1'],
             note='S and rS share every term except the first term of S and the last term of rS.'),
          tf('For r ≠ 1, a + ar + ... + ar^(n-1) = a(1 - r^n) ÷ (1 - r).', key=True, note='This is the geometric series formula.'),
          tf('1 + 3 + 9 + 27 = 3⁴', key=False, note='The sum is 40, and 3⁴ = 81.'),
      ]),
      f2=B('Use logarithms to turn equal factors into equal differences', 'HSF-BF.B.5', [
          sa('g(x) = 4 · 2^x.\nShow that log₂ g(x) = x + 2.', 'Answer:', key='log₂(4 · 2^x) = log₂ 4 + log₂ 2^x = 2 + x.', note='Form required: the steps.'),
          sa('y = 10^x.\nWhat is log y?', 'log y =', key='x', note='Any equivalent form.'),
          mc('The values y = 1, 10, 100, 1,000 occur at x = 0, 1, 2, 3.\nWhat are the values of log y?', ['0, 1, 2, 3', '1, 10, 100, 1,000', '0, 10, 20, 30', '1, 2, 3, 4'],
             note='log 10^k = k.'),
          tf('Taking the logarithm of an exponential function a · b^x gives a linear function of x.', key=True, note='log(a · b^x) = log a + x log b.'),
          tf('log(100 · 10^x) = 100x', key=False, note='log(100 · 10^x) = 2 + x.'),
      ])),

