              mc('A cyclist rides 12 miles in 3 hours at a constant rate.\nWhat is the constant of proportionality in miles per hour?', ['4', '36', '{1/4}', '15'], note='12 ÷ 3.'),
              tf('In y = 9x, y increases by 9 whenever x increases by 1.', key=True, note='9 is the unit rate.'),
