              sa('A phone battery is at 80% and drops 5 percentage points per hour.\nWrite a function B(t) for the charge after t hours.', 'B(t) =', key='80 - 5t', note='Any equivalent form.'),
              mc('Which function has rate of change 0.8 and initial value 6?', ['y = 0.8x + 6', 'y = 6x + 0.8', 'y = 6.8x', 'y = 6(0.8)^x'], note='y = mx + b with m = 0.8 and b = 6.'),
              tf('A function with initial value 10 and rate of change -2 is y = 10 - 2x.', key=True, note='b = 10 and m = -2.'),
